SELECT "dest", mode() WITHIN GROUP (ORDER BY "arr_delay", "arr_time") AS "median_delay"
FROM "flights"
GROUP BY "dest";

SELECT "dest", duck(0.5) WITHIN GROUP (ORDER BY "arr_delay") AS "duck_delay"
FROM "flights"
GROUP BY "dest";

CREATE TABLE unit (
    total_profit BOOLEAN GENERATED ALWAYS AS((SELECT 1)) VIRTUAL,
    word VARCHAR,
    price INTEGER,
    amount_sold INTEGER,
);
